package com.bank.stream.service;

import com.bank.stream.model.KafkaRecord;
import java.util.List;
import java.util.logging.Logger;

// Simulates a Kafka source that tracks the committed offset in a checkpoint.
public class KafkaSourceSim {

    private static final Logger log = Logger.getLogger(KafkaSourceSim.class.getName());
    private long committedOffset = -1;   // checkpointed, not Kafka consumer group

    // Return only records beyond the last committed offset (resume semantics).
    public List<KafkaRecord> poll(List<KafkaRecord> topic) {
        List<KafkaRecord> fresh = topic.stream()
                .filter(r -> r.getOffset() > committedOffset)
                .toList();
        log.info(() -> "Polled " + fresh.size() + " records after offset " + committedOffset);
        return fresh;
    }

    // Commit the max offset processed in a batch to the checkpoint.
    public void commit(long maxOffset) {
        committedOffset = Math.max(committedOffset, maxOffset);
        log.info(() -> "Committed offset " + committedOffset + " to checkpoint");
    }

    public long getCommittedOffset() { return committedOffset; }
}
