package com.bank.stream.service;

import com.bank.stream.model.KafkaRecord;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// Simulates a downstream consumer that deduplicates by business key.
public class IdempotentKafkaSink {

    private static final Logger log = Logger.getLogger(IdempotentKafkaSink.class.getName());
    private final Set<String> deliveredKeys = new HashSet<>();

    // Produce enriched records; a retried key is ignored (exactly-once effect).
    public int produce(List<KafkaRecord> enriched) {
        int newlyDelivered = 0;
        for (KafkaRecord r : enriched) {
            if (deliveredKeys.add(r.getKey())) {
                newlyDelivered++;
                log.info(() -> "Produced enriched record key=" + r.getKey());
            } else {
                log.warning(() -> "Duplicate key " + r.getKey() + " ignored (idempotent)");
            }
        }
        return newlyDelivered;
    }
}
