package com.bank.stream;

import com.bank.stream.model.KafkaRecord;
import com.bank.stream.service.IdempotentKafkaSink;
import com.bank.stream.service.KafkaSourceSim;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: Kafka source with offsets + idempotent sink → no duplicates.
public class KafkaStreamingDemo {

    private static final Logger log = Logger.getLogger(KafkaStreamingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        KafkaSourceSim source = new KafkaSourceSim();
        IdempotentKafkaSink sink = new IdempotentKafkaSink();

        List<KafkaRecord> topic = List.of(
            new KafkaRecord("T1", "{acct:SAV2001,amt:50000}", 0),
            new KafkaRecord("T2", "{acct:CUR3001,amt:12000}", 1),
            new KafkaRecord("T3", "{acct:SAV2001,amt:3000}", 2));

        // Batch A: poll, produce, commit.
        var batchA = source.poll(topic);
        int deliveredA = sink.produce(batchA);
        log.info(() -> "Batch A delivered " + deliveredA + " records");
        source.commit(2);

        // Simulated failure BEFORE commit of a reprocessed batch:
        // reset to pretend the commit was lost, reprocess offset 2 again.
        log.info("--- simulated retry of last record after transient failure ---");
        var retry = List.of(topic.get(2)); // T3 re-sent
        int deliveredRetry = sink.produce(retry);
        log.info(() -> "Retry delivered " + deliveredRetry + " NEW records (T3 dedup → 0)");

        log.info("Kafka streaming exactly-once demo complete.");
    }
}
